Definition cut_pc (c : nat) : Z :=
  match c with 0%nat => 0xd332c | 1%nat => 0xd336c | 2%nat => 0xd33b4 | 3%nat => 0xd33d8 | 4%nat => 0xd3440
             | 5%nat => 0xd34c8 | 6%nat => 0xd354c | 7%nat => 0xd356c | 8%nat => 0xd35d0 | _ => 0xd36b0 end.
Definition cut_rank (c : nat) : Z :=
  match c with 2%nat | 6%nat => 0 | 9%nat => 2 | _ => 1 end.
(* [comment removed for export] *)
Definition cut_it (c : nat) (p : Z) : Z := match c with 4%nat | 9%nat => p - 1 | _ => p end.
(* [comment removed for export] *)
Definition cut_rel (c : nat) (p : Z) (w2 w3 w4 w5 w6 : word) : Prop :=
  match c with
  | 0%nat | 2%nat | 6%nat => w2 = wz p
  | 1%nat => w2 = wz p /\ w3 = wz p
  | 3%nat => w4 = wz p /\ w3 = wz p /\ w2 = wz (p + 1) /\ w6 = wz (p + 2)
  | 4%nat => w2 = wz p /\ w3 = wz (p - 1) /\ w6 = wz (p + 1)
  | 5%nat => w2 = wz p /\ w4 = wz p
  | 7%nat => w4 = wz p /\ w2 = wz p /\ w3 = wz (p + 1) /\ w5 = wz (p + 1)
  | 8%nat => w2 = wz p /\ w4 = wz (p - 1)
  | _ => w5 = wz p /\ w3 = wz p
  end.
Definition cut_side (c : nat) (p itv it0 L : Z) : Prop :=
  itv = cut_it c p /\ it0 <= cut_it c p /\ cut_it c p < L.

